-- 0161_finance_year_end_lapse_memo.sql
-- UAT T-PERIOD (bundle 19, ERP-head decisions 2026-11-05 under the owner delegated authority):
--  1. gl.finance_change_requests.kind gains period_reopen: reopening a HARD-closed month is a maker-checker
--     change (a second finance_admin approves) when the tenant has the second-approver setting on (default).
--  2. gl.finance_opening_balances.source: manual (entered by an officer) | fy_close (generated by the year-end
--     close for the carry-forward heads only). Existing rows are manual.
--  3. gl.finance_year_end_runs: one row per (tenant, closed FY): when the year-end close last ran, by whom, why,
--     what it generated (idempotent re-runs update the row; every run is audited).
--  4. budget.finance_budget_lapses: the 31 March lapse statement recorded by the year-end close, one row per
--     budget head: final grant (RE, after supplementary grants and re-appropriation) - expenditure = unspent
--     provision that lapses (GFR: unspent provision is not carried forward).
--  5. gl.depreciation_memo: depreciation that is computed and kept for the registers but NOT posted to the GL:
--     the income-tax (statutory WDV) book always, and the company book for a cash-basis tenant.
-- Additive and idempotent. Rollback: DROP the three new tables; ALTER TABLE gl.finance_opening_balances DROP
-- COLUMN source; restore the previous kind CHECK (only once no period_reopen request exists).

SET lock_timeout = '5s';

ALTER TABLE gl.finance_change_requests DROP CONSTRAINT IF EXISTS finance_change_requests_kind_check;
ALTER TABLE gl.finance_change_requests ADD CONSTRAINT finance_change_requests_kind_check
  CHECK (kind IN ('fiscal_year_activate', 'opening_balances_enter', 'hoa_change', 'settings_relax', 'period_reopen'));

ALTER TABLE gl.finance_opening_balances ADD COLUMN IF NOT EXISTS source varchar(16) NOT NULL DEFAULT 'manual';
ALTER TABLE gl.finance_opening_balances DROP CONSTRAINT IF EXISTS finance_opening_balances_source_check;
ALTER TABLE gl.finance_opening_balances ADD CONSTRAINT finance_opening_balances_source_check
  CHECK (source IN ('manual', 'fy_close'));

CREATE TABLE IF NOT EXISTS gl.finance_year_end_runs (
  tenant_id              uuid        NOT NULL,
  fy_code                varchar(9)  NOT NULL,
  next_fy_code           varchar(9)  NOT NULL,
  opening_balance_count  integer     NOT NULL DEFAULT 0,
  fund_carried_minor     bigint      NOT NULL DEFAULT 0,
  lapse_total_minor      bigint      NOT NULL DEFAULT 0,
  run_count              integer     NOT NULL DEFAULT 1,
  reason                 text        NOT NULL,
  run_by                 uuid        NOT NULL,
  run_at                 timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, fy_code)
);

CREATE TABLE IF NOT EXISTS budget.finance_budget_lapses (
  tenant_id         uuid        NOT NULL,
  fy                char(7)     NOT NULL,
  head_id           uuid        NOT NULL,
  budget_id         uuid        NOT NULL,
  be_minor          bigint      NOT NULL,
  re_minor          bigint      NOT NULL,
  expenditure_minor bigint      NOT NULL,
  lapse_minor       bigint      NOT NULL CHECK (lapse_minor >= 0),
  excess_minor      bigint      NOT NULL CHECK (excess_minor >= 0),
  recorded_by       uuid        NOT NULL,
  recorded_at       timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, fy, head_id)
);

CREATE TABLE IF NOT EXISTS gl.depreciation_memo (
  tenant_id    uuid        NOT NULL,
  asset_id     uuid        NOT NULL,
  period       varchar(7)  NOT NULL,
  dep_book     varchar(16) NOT NULL CHECK (dep_book IN ('company', 'statutory')),
  amount_minor bigint      NOT NULL CHECK (amount_minor >= 0),
  basis        varchar(8)  NOT NULL CHECK (basis IN ('cash', 'accrual')),
  reason       varchar(32) NOT NULL,
  created_by   uuid        NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, asset_id, period, dep_book)
);

-- RLS (same file as the CREATE TABLE, house style: hrms 0135_audit_hr_action_log.sql).
ALTER TABLE gl.finance_year_end_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE gl.finance_year_end_runs FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation_policy ON gl.finance_year_end_runs;
CREATE POLICY tenant_isolation_policy ON gl.finance_year_end_runs
  USING (tenant_id = budget.current_tenant_id()) WITH CHECK (tenant_id = budget.current_tenant_id());

-- RLS (same file as the CREATE TABLE, house style: hrms 0135_audit_hr_action_log.sql).
ALTER TABLE budget.finance_budget_lapses ENABLE ROW LEVEL SECURITY;
ALTER TABLE budget.finance_budget_lapses FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation_policy ON budget.finance_budget_lapses;
CREATE POLICY tenant_isolation_policy ON budget.finance_budget_lapses
  USING (tenant_id = budget.current_tenant_id()) WITH CHECK (tenant_id = budget.current_tenant_id());

-- RLS (same file as the CREATE TABLE, house style: hrms 0135_audit_hr_action_log.sql).
ALTER TABLE gl.depreciation_memo ENABLE ROW LEVEL SECURITY;
ALTER TABLE gl.depreciation_memo FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation_policy ON gl.depreciation_memo;
CREATE POLICY tenant_isolation_policy ON gl.depreciation_memo
  USING (tenant_id = budget.current_tenant_id()) WITH CHECK (tenant_id = budget.current_tenant_id());

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'finance_svc') THEN
    GRANT USAGE ON SCHEMA gl TO finance_svc;
    GRANT USAGE ON SCHEMA budget TO finance_svc;
    GRANT SELECT, INSERT, UPDATE ON gl.finance_year_end_runs, budget.finance_budget_lapses, gl.depreciation_memo TO finance_svc;
    -- the year-end close replaces its own (source = fy_close) rows when it is re-run
    GRANT SELECT, INSERT, UPDATE, DELETE ON gl.finance_opening_balances TO finance_svc;
  END IF;
END
$$;
